async def search_multimodal(query_vec_768, query_patches_32x128, timeout_ms=180):
    try:
        # 1. Parallel 48-shard scatter-gather with 18ms replica hedging
        hnsw_hits, diskann_hits, bm25_hits = await scatter_with_hedge(
            query_vec_768, hedge_after_ms=18, budget_ms=45
        )
        # 2. Rank-only Reciprocal Rank Fusion (k=60) -> top-200
        candidates = reciprocal_rank_fusion([hnsw_hits, diskann_hits, bm25_hits], k=60, limit=200)
        # 3. Circuit-broken ColPali MaxSim reranking
        if maxsim_circuit_breaker.allow():
            reranked = await avx512_maxsim_rerank(query_patches_32x128, candidates, timeout_ms=65)
            return temporal_collapse_video(reranked, window_sec=5)[:20]
        return temporal_collapse_video(candidates, window_sec=5)[:20]
    except TimeoutError:
        return fallback_rrf_top_k(candidates, k=20)

